css:
:root {
  --font-sans: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}
body,
:is([data-slot="sidebar"], [data-chat-header], .messages-timeline-scroll, [data-user-message-bubble], .chat-markdown, [data-slot="composer-host"], .composer-tiptap, [data-thread-details-card], [data-settings-page-scroll], [data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="tooltip-popup"]),
[data-slot="button"],
[data-slot="input"],
[data-slot="select-trigger"] {
  font-family: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
  font-kerning: normal;
}
:is([data-slot="sidebar"], [data-chat-header], .messages-timeline-scroll, [data-user-message-bubble], .chat-markdown, [data-slot="composer-host"], .composer-tiptap, [data-thread-details-card], [data-settings-page-scroll], [data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="tooltip-popup"]) :where(p, span, a, button, input, textarea, div, label, h1, h2, h3, h4, h5, h6, li, td, th, summary, time):not(:where(code *, pre *, kbd *, samp *, .chat-markdown-codeblock, .chat-markdown-codeblock *, [data-thread-terminal-drawer], [data-thread-terminal-drawer] *)) {
  font-family: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}
.chat-markdown,
[data-user-message-bubble],
.composer-tiptap {
  font-size: 1rem;
  line-height: 1.65;
  letter-spacing: normal;
}
.chat-markdown :is(h1, h2, h3, h4, h5, h6) {
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.02em;
  text-wrap: balance;
}
.chat-markdown :is(strong, b) {
  font-weight: 600;
}
[data-chat-header], [data-thread-item] {
  letter-spacing: -0.01em;
}
:is(code, pre, kbd, samp, .chat-markdown-codeblock),
:is(code, pre, kbd, samp, .chat-markdown-codeblock) * {
  font-family: var(--font-mono, ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace) !important;
  letter-spacing: normal;
}


.dark [data-workspace-area="conversation"],
.dark [data-chat-composer-overlay="true"].items-center {
  background:
    var(--theme-background-image) right bottom / cover no-repeat,
    #0d0e19 !important;
}
.dark .messages-timeline-scroll { background: transparent !important; }
.dark [data-slot="sidebar"] {
  background: #151521 !important;
  border-right: 1px solid #343045 !important;
}
.dark [data-slot="sidebar-inner"] {
  background: #151521 !important;
}
.dark [data-slot="sidebar"] .drag-region:has(a[aria-label="T3 Code home"]) {
  background: #1d1b2b !important;
  box-shadow: inset 0 -1px #393449, inset 0 1px #ffffff09;
}
.dark [data-slot="sidebar"] a[aria-label="T3 Code home"] {
  color: #f0e9f8 !important;
}
.dark [data-slot="sidebar-footer"] {
  box-shadow: inset 0 1px #393449;
}
.dark [data-chat-header] {
  background: #191826 !important;
  border-bottom: 1px solid #3b354b !important;
  box-shadow: 0 3px 12px #08071069, inset 0 1px #ffffff09;
  backdrop-filter: none;
}
.dark [data-slot="sidebar"] [data-sidebar-row][aria-current]:not([aria-current="false"]) {
  background: #282439 !important;
  box-shadow: inset 0 0 0 1px #534766, 0 2px 6px #0807104d;
}
.dark [data-slot="sidebar"] [data-sidebar-row][aria-current]:not([aria-current="false"]):hover {
  background: #2e293f !important;
}
.dark [data-slot="sidebar"] [data-sidebar-row]:focus-visible {
  outline: 1px solid #c2aff0;
  outline-offset: -2px;
}
.dark .topbar-scroll-fade:has([data-changed-files-state="tree"]) {
  mask: none;
}
.dark [data-changed-files-state="tree"] {
  background: linear-gradient(155deg, #28253ca8, #14132185);
  backdrop-filter: blur(16px) saturate(120%);
  box-shadow: inset 0 0 0 1px #ddd0f41c, 0 6px 18px #09081240;

  & > [data-changed-files-header] {
    background: #d7c9ff08;
    backdrop-filter: blur(8px);
  }
}
.dark [data-thread-details-card] {
  background: linear-gradient(140deg,#30273fe8,#1c1929ee) !important;
  border: 1px solid #ae9bc345 !important;
  box-shadow: 0 12px 35px #08061245, inset 0 1px #e7d7fc11;
  backdrop-filter: blur(18px) saturate(115%);
}
.dark [data-slot="composer-host"] {
  --chat-composer-outline: transparent;
  --chat-composer-highlight: transparent;
  background:
    radial-gradient(ellipse 120% 95% at 8% -28%, #a9dfd124, transparent 67%) border-box,
    linear-gradient(transparent calc(100% - 15px), #050b1150) border-box,
    radial-gradient(125% 105% at 22% 0%, #293f40 0%, #202f34 19%, transparent 49%),
    linear-gradient(151deg, #242e35 0%, #202930 32%, #1e262e 63%, #1c242c 100%) !important;
  border: 1px solid rgb(225 239 238 / 10%) !important;
  border-radius: 18px;
  color: #e3efed;
  box-shadow:
    inset 1px 2px 3px -1px #b5e4d95c,
    inset -1px -2px 4px -1px #04090f9e,
    0 2px 3px -1px #04080de0,
    2px 8px 16px -6px #04080db8;
}
.dark [data-slot="composer-host"]::before {
  background: none;
  backdrop-filter: none;
}
.dark [data-chat-composer-form] {
  .composer-tiptap {
    caret-color: #a8d8cb;
  }
  [data-chat-provider-model-picker] {
    color: #dde9e6;
    &:focus-visible {
      outline: 2px solid #b5e6d9;
      outline-offset: 2px;
    }
    @media (hover: hover) {
      &:enabled:hover {
        background: #92cfc021;
        color: #f0faf7;
      }
    }
  }
  button:is(
    .rounded-full.bg-message-action,
    .rounded-full.isolate.overflow-hidden[type="submit"],
    .rounded-full[class~="bg-destructive/90"],
    [data-chat-composer-transition-actions],
    [aria-label$=" voice input"],
    [aria-label="Attach files"],
    [data-slot="voice-input-pill"] > :not([aria-label])
  ) {
    --chamfer: inset 1px 1px 2px #d5f5e75c, 1px 2px 3px -1px #03090de0;
    --depressed: inset 1px 2px 3px #03090d8c;
    background: linear-gradient(145deg, #a0cebf, #73a69b);
    color: #122b29;
    box-shadow: var(--chamfer);
    scale: none;
    transition: background-color 95ms ease-out, box-shadow 95ms ease-out, filter 95ms ease-out;

    &:is([aria-label="Queue message"], [aria-label="Update queued message"]) {
      background: linear-gradient(145deg, #705685, #4a395c);
      color: #f4e8ff;
    }
    &[aria-label="Steer message"] {
      background: linear-gradient(145deg, #595580, #3e385a);
      color: #f0eafa;
    }
    &:is([class~="bg-destructive/90"], [aria-label="Cancel voice input"]) {
      background: linear-gradient(145deg, #9a5861, #673a47);
      color: #fff0f2;
    }
    &:disabled {
      background: #303340;
      box-shadow: var(--depressed);
      color: #b8bed0;
      opacity: 1;
    }
    &:disabled[class~="bg-destructive/90"] {
      background: #50343c;
      color: #dbafb8;
    }
    &:disabled:has(> svg:not([class]) > path[stroke="currentColor"]) {
      background: #26373a linear-gradient(#ffffff0c, transparent);
      box-shadow: inset 0 0 0 1px #b9e4d630;
      color: #a0bab7;
      cursor: default;
      @media (hover: hover) and (pointer: fine) {
        pointer-events: auto;
        &:hover { background-color: #30474a; }
      }
    }
    &:enabled:focus-visible {
      outline: 2px solid #b5e6d9;
      outline-offset: 2px;
    }
    @media (hover: hover) and (pointer: fine) {
      &:enabled:hover:not(:active) { filter: brightness(1.14); }
    }
    &:enabled:active {
      box-shadow: var(--depressed);
      filter: brightness(.90);
      transition-duration: 45ms;
    }
    &:is([aria-label="Attach files"], [aria-label="Start voice input"], [data-slot="voice-input-pill"] > :not([aria-label])) {
      --chamfer: inset 1px 1px 2px #b9e4d629, 1px 2px 3px -1px #03090da6;
      background: linear-gradient(145deg, #b2e7d616, #4a686512);
      color: #d0e5e0;
      &:enabled:active { background-color: #233332; }
      &:disabled { opacity: .65; }
      @media (hover: hover) and (pointer: fine) {
        &:enabled:hover:not(:active) {
          background-color: #2d4644;
          color: #f0faf7;
          filter: none;
        }
      }
    }
    @media (prefers-reduced-motion: reduce) {
      &, &:enabled:active { transition: none; }
    }
  }
  button:is(.rounded-full.bg-message-action, [data-chat-composer-transition-actions])
    svg:not([class]) path[stroke="currentColor"] {
    stroke-width: 1.6;
  }
}

.dark [data-user-message-bubble] {
  background: #25283c !important;
  border: 1px solid #899cba3d;
}
.dark .chat-markdown-codeblock { background: #12111cf5 !important; }
.dark :is([data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]) {
  background: #211e2ff5 !important;
  border-color: #85719d4d !important;
  backdrop-filter: blur(18px);
}
.dark .composer-tiptap [data-placeholder]::before,
.dark .composer-tiptap::before { color: #bdcecd !important; }
.dark [data-thread-item] { border-radius: 10px; }
.dark ::selection { background: #826ba877; color: #f2eafa; }
.dark ::-webkit-scrollbar-thumb { background: #73638580; border-radius: 8px; }
.dark ::-webkit-scrollbar-thumb:hover { background: #9682afaa; }

.dark [data-slot="button"][class~="bg-destructive"] {
  --destructive: #a34250;
}
